function li_locale():string{$supported=['tr','en','de','fr','es','it','pt','ru','ar','fa','nl','zh','ja','ko'];$pick=(string)($_POST['lang']??$_GET['lang']??'');if($pick==='')foreach(explode(',',(string)($_SERVER['HTTP_ACCEPT_LANGUAGE']??'')) as $part){$code=strtolower(substr(trim($part),0,2));if(in_array($code,$supported,true)){$pick=$code;break;}}return in_array($pick,$supported,true)?$pick:'en';}
