function li_db():PDO{static $db;if(!$db){$path=li_env('LICENSE_DB_PATH',LC_INSTALL_ROOT.'/storage/licenses.sqlite');if(!is_dir(dirname($path)))mkdir(dirname($path),0700,true);$db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}$db->exec('PRAGMA foreign_keys=ON');return $db;}
function li_requirements():array{$storage=li_env('LICENSE_STORAGE_PATH',LC_INSTALL_ROOT.'/storage');return ['PHP 8.2+'=>version_compare(PHP_VERSION,'8.2.0','>='),'PDO SQLite'=>extension_loaded('pdo_sqlite'),'SQLite3'=>extension_loaded('sqlite3'),'cURL'=>extension_loaded('curl'),'OpenSSL'=>extension_loaded('openssl'),'JSON'=>extension_loaded('json'),'Mbstring'=>extension_loaded('mbstring'),'Storage writable'=>is_dir($storage)?is_writable($storage):is_writable(dirname($storage)),'HTTPS or local'=>!empty($_SERVER['HTTPS'])||in_array($_SERVER['SERVER_NAME']??'', ['localhost','127.0.0.1'], true)];}
function li_html(string $title,string $body):never{$lang=htmlspecialchars(li_locale(),ENT_QUOTES,'UTF-8');$dir=in_array(li_locale(),['ar','fa'],true)?'rtl':'ltr';$links=implode(' ',array_map(static fn(string $l):string=>'<a href="?lang='.$l.'">'.$l.'</a>',['tr','en','de','fr','es','it','pt','ru','ar','fa','nl','pl','uk','ro']));echo '<!doctype html><html lang="'.$lang.'" dir="'.$dir.'"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').' · TofiDesk</title><style>body{font:15px/1.6 Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:linear-gradient(135deg,#061f2d,#0d5264);color:#153346;margin:0;min-height:100vh}.box{max-width:1040px;margin:48px auto;padding:42px;background:#f7faf8;border-radius:24px;box-shadow:0 25px 80px #00141f66}.box:before{content:\"TOFIDESK\";display:block;color:#ff7c2c;font-size:13px;font-weight:800;letter-spacing:3px;margin-bottom:28px}.box h1{font-size:clamp(30px,4vw,48px);line-height:1.08;letter-spacing:-1.5px;color:#08283a;margin:20px 0 12px}.box h2{font-size:18px;color:#08283a;margin-top:30px}.box p{color:#61757c}.box ul{list-style:none;padding:0}.box li{padding:12px 15px;margin:7px 0;border:1px solid #dce8e3;border-radius:10px;background:#fff}.ok{color:#16834b}.bad{color:#b42318}label{display:block;margin:16px 0;font-weight:700;color:#365665}input{display:block;width:100%;box-sizing:border-box;padding:13px 14px;margin-top:7px;border:1px solid #cbdad8;border-radius:9px;background:#fff}button{background:#ff7c2c;color:#08283a;border:0;border-radius:9px;padding:14px 22px;font-weight:800;cursor:pointer;box-shadow:0 8px 18px #ff7c2c44}.langs{text-align:right}.langs a{display:inline-block;margin:0 3px;padding:5px 7px;color:#087f8c;font-weight:700;text-decoration:none}.langs a:hover{background:#e8f3ef;border-radius:6px}@media(max-width:760px){.box{margin:0;padding:26px 20px;border-radius:0;min-height:100vh}}</style><main class="box"><nav class="langs">'.$links.'</nav><h1>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'</h1>'.$body.'</main></html>';exit;}
$token='';
$checks=li_requirements();$errors=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));if($errors)li_html(li_t('requirements'),'<p class="bad">'.htmlspecialchars(li_t('resolve'),ENT_QUOTES,'UTF-8').'</p><ul>'.implode('',array_map(static fn(string $name):string=>'<li class="bad">✗ '.htmlspecialchars($name,ENT_QUOTES,'UTF-8').'</li>',$errors)).'</ul>');
try{li_db()->exec('CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');if(li_db()->query('SELECT id FROM admins LIMIT 1')->fetch())li_html(li_t('already'),'<p>'.htmlspecialchars(li_t('already_help'),ENT_QUOTES,'UTF-8').' <a href="./login">'.htmlspecialchars(li_t('login'),ENT_QUOTES,'UTF-8').'</a></p>');}catch(Throwable $e){li_html(li_t('dbfail'),'<p class="bad">'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</p>');}
if($_SERVER['REQUEST_METHOD']==='POST'){$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(!$email||strlen($password)<12)li_html(li_t('invalid'),'<p class="bad">'.htmlspecialchars(li_t('invalid_help'),ENT_QUOTES,'UTF-8').'</p>');$stmt=li_db()->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)');$stmt->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: ./login');exit;}
